using System;using System.IO;using System.Windows.Forms;
namespace SargasPC {public sealed partial class Window {
 private void FindingsChoice(){using(var d=new Form{Text="Peržiūrėti radinius",Width=620,Height=270,StartPosition=FormStartPosition.CenterParent}){var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),FlowDirection=FlowDirection.TopDown,WrapContents=false};var local=new Button{Text="Šios paskyros radiniai ir karantinas",Width=550,Height=65};var service=new Button{Text="Paslaugos radiniai (administratoriaus langas)",Width=550,Height=65};local.Click+=(s,e)=>{d.Close();ResponseCenter();};service.Click+=(s,e)=>{d.Close();LaunchCaseReview();};layout.Controls.AddRange(new Control[]{local,service});d.Controls.Add(layout);ThemeDialog(d);d.ShowDialog(this);}}
 private void SimpleUpdates(){using(var d=new Form{Text="Atnaujinimai",Width=770,Height=510,StartPosition=FormStartPosition.CenterParent}){var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),FlowDirection=FlowDirection.TopDown,WrapContents=false};var note=new Label{Width=700,Height=140,Text=core.SharedReadOnlyEngine?"Bendras ClamAV bazes atnaujina paslauga. Mygtukas atvers administratoriaus langą tikram vienkartiniam atnaujinimui užsakyti. Ten galima aiškiai leisti vieną atnaujinimą naudojant bateriją. Programos leidėjo raktas ir atnaujinimų serveris šioje bandomojoje laidoje dar nesukonfigūruoti.":"ClamAV bazės atnaujinamos iš oficialių serverių. Atsisiuntimas gali būti didelis; jūsų failai nesiunčiami. Programos atnaujinimo patikra yra atskira nuo virusų bazių. Leidėjo raktas ir atnaujinimų serveris šioje bandomojoje laidoje dar nesukonfigūruoti."};var db=new Button{Text=core.SharedReadOnlyEngine?"Atnaujinti bendras bazes (administratorius)…":"Atnaujinti vietines ClamAV bazes",Width=700,Height=60};db.Click+=(s,e)=>{d.Close();if(core.SharedReadOnlyEngine){LaunchDatabaseUpdate();return;}if(Confirm("Atnaujinti virusų bazes?","Reikia interneto. FreshClam tikrins oficialių bazių parašus. Atsisiuntimas gali užtrukti."))Run("ClamAV bazių atnaujinimas",()=>core.UpdateLocalEngine(),true);};var app=new Button{Text="Patikrinti pasirašytą programos atnaujinimą…",Width=700,Height=60};app.Click+=(s,e)=>{d.Close();VerifyUpdate();};var feed=new Button{Text="Papildomos MalwareBazaar sumos ir rakto būsena…",Width=700,Height=60};feed.Click+=(s,e)=>{d.Close();FeedDialog();};layout.Controls.AddRange(new Control[]{note,db,feed,app});d.Controls.Add(layout);ThemeDialog(d);d.ShowDialog(this);}}
 private void StartNativeAudit(){if(Confirm("Atlikti Windows kontrolinę patikrą?","Bus sukurti tik nuosavi neutralūs bandymo failai: patikrinta DPAPI kopija, atkūrimas ir originalo izoliavimas. Vienas neutralus failas bus patikrintas ClamAV. EICAR ir gyvi virusai nenaudojami. Išsaugoma vietinė ataskaita; bendras CPU apima ir kitas programas. Tai ne visos apsaugos sertifikavimas."))Run("Windows kontrolė ir apkrova",()=>NativeAudit.Run(core),true);}
}}
